import sys

class TrieBrute:
    def __init__(self):
        self.words = set()
    def insert(self, word: str) -> None:
        self.words.add(word)
    def search(self, word: str) -> bool:
        return word in self.words
    def startsWith(self, prefix: str) -> bool:
        for w in self.words:
            if w.startswith(prefix):
                return True
        return False

def run_brute(lines):
    t = TrieBrute()
    out = []
    for op, arg in lines:
        if op == 'insert':
            t.insert(arg)
        elif op == 'search':
            out.append('true' if t.search(arg) else 'false')
        elif op == 'startsWith':
            out.append('true' if t.startsWith(arg) else 'false')
    return out

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if not data: sys.exit(0)
    q = int(data[0].strip())
    lines = []
    for i in range(1, q + 1):
        parts = data[i].split(' ', 1)
        op = parts[0]
        arg = parts[1] if len(parts) > 1 else ''
        lines.append((op, arg))
    for r in run_brute(lines):
        print(r)

import sys

class Node:
    __slots__ = ('children', 'is_end')
    def __init__(self):
        self.children = {}
        self.is_end = False

class TrieOpt:
    def __init__(self):
        self.root = Node()
    def insert(self, word: str) -> None:
        cur = self.root
        for ch in word:
            if ch not in cur.children:
                cur.children[ch] = Node()
            cur = cur.children[ch]
        cur.is_end = True
    def search(self, word: str) -> bool:
        cur = self.root
        for ch in word:
            if ch not in cur.children: return False
            cur = cur.children[ch]
        return cur.is_end
    def startsWith(self, prefix: str) -> bool:
        cur = self.root
        for ch in prefix:
            if ch not in cur.children: return False
            cur = cur.children[ch]
        return True

if __name__ == '__main__':
