        self.root = Node2()
    def insert(self, word: str) -> None:
        cur = self.root
        for ch in word:
            idx = ord(ch) - ord('a')
            if cur.children[idx] is None:
                cur.children[idx] = Node2()
            cur = cur.children[idx]
        cur.is_end = True
    def search(self, word: str) -> bool:
        cur = self.root
        for ch in word:
            idx = ord(ch) - ord('a')
            if cur.children[idx] is None: return False
            cur = cur.children[idx]
        return cur.is_end
    def startsWith(self, prefix: str) -> bool:
        cur = self.root
        for ch in prefix:
            idx = ord(ch) - ord('a')
            if cur.children[idx] is None: return False
            cur = cur.children[idx]
        return True

